    ("Barely ______ the manuscript been authenticated when a private collector offered millions for it.", ["has", "had", "was", "did"], 1, "Trpná inverze: 'Barely had the manuscript been authenticated...'.", "Authenticate = ověřit pravost."),
    ("Hardly ______ the whistle blown when the home crowd erupted into thunderous applause.", ["has", "had", "was", "did"], 1, "Správná inverze v trpném rodě: 'Hardly had the whistle been blown...' nebo činném 'had the whistle blown'.", "Věžně 'had' před podmětem."),

    # No sooner ... than (21-35)
    ("No sooner had the keynote speaker begun ______ the microphone cut out completely.", ["when", "than", "that", "then"], 1, "Druhý stupeň 'sooner' vyžaduje srovnávací spojku 'than'.", "No sooner = THAN."),
    ("No sooner ______ boarded the train than I realized I had left my passport at the café.", ["I had", "had I", "did I", "have I"], 1, "Po 'No sooner' následuje inverze: 'No sooner had I boarded...'.", "Inverze + THAN."),
    ("No sooner had the ceasefire been signed ______ artillery fire echoed in the valley.", ["when", "than", "as", "until"], 1, "Ustálená vazba: 'No sooner had... than...'.", "Sooner je 2. stupeň ➔ vždy THAN."),
    ("No sooner ______ launched the smartphone than competitors announced a similar model.", ["the firm had", "had the firm", "did the firm", "has the firm"], 1, "Podmět 'the firm' stojí až za pomocným slovesem 'had'.", "Inverze platí pro firmy i instituce."),
    ("No sooner did the snow melt ______ gardeners began planting spring bulbs.", ["when", "than", "then", "that"], 1, "Pozor: 'No sooner' může výjimečně mít i Past Simple ('did... melt'), ale spojka je stále 'than'!", "No sooner did + V1 ... THAN."),
    ("No sooner ______ the suspect left the building than undercover officers moved in.", ["has", "had", "was", "did"], 1, "S příčestím 'left' tvoříme předminulý čas: 'No sooner had the suspect left...'.", "Had + V3."),
